SELECT jsonb_pretty(jsonb_build_object(
  'schema_revision', (SELECT version_num FROM alembic_version),
  'warehouses', (SELECT jsonb_build_object('rows', count(*), 'fingerprint', md5(coalesce(string_agg(jsonb_build_array(id, company_id, branch_id, code, is_central)::text, E'\n' ORDER BY id), ''))) FROM warehouses),
  'lots', (SELECT jsonb_build_object('rows', count(*), 'fingerprint', md5(coalesce(string_agg(jsonb_build_array(id, company_id, purchase_id, code, received_at, label_confirmation_required)::text, E'\n' ORDER BY id), ''))) FROM inventory_lots),
  'lot_details', (SELECT jsonb_build_object('rows', count(*), 'accepted_quantity_base', coalesce(sum(accepted_quantity_base), 0), 'fingerprint', md5(coalesce(string_agg(jsonb_build_array(id, company_id, inventory_lot_id, purchase_detail_id, inventory_item_id, product_id, base_unit_id, quantity_received, quantity_accepted, accepted_quantity_base)::text, E'\n' ORDER BY id), ''))) FROM inventory_lot_details),
  'handling_units', (SELECT jsonb_build_object('rows', count(*), 'quantity_base', coalesce(sum(quantity_base), 0), 'fingerprint', md5(coalesce(string_agg(jsonb_build_array(id, company_id, warehouse_id, location_id, inventory_item_id, inventory_lot_id, inventory_lot_detail_id, code, quantity_base, stock_status, closed_at)::text, E'\n' ORDER BY id), ''))) FROM inventory_handling_units),
  'balances', (SELECT jsonb_build_object('rows', count(*), 'quantity_base', coalesce(sum(quantity_base), 0), 'fingerprint', md5(coalesce(string_agg(jsonb_build_array(id, company_id, warehouse_id, location_id, inventory_item_id, stock_status, lot_code, expiry_date, quantity_base)::text, E'\n' ORDER BY id), ''))) FROM inventory_balances),
  'movements', (SELECT jsonb_build_object('rows', count(*), 'fingerprint', md5(coalesce(string_agg(jsonb_build_array(id, company_id, movement_type, source_reference, posted_at, posted_by)::text, E'\n' ORDER BY id), ''))) FROM inventory_movements),
  'movement_lines', (SELECT jsonb_build_object('rows', count(*), 'quantity_base', coalesce(sum(quantity_base), 0), 'fingerprint', md5(coalesce(string_agg(jsonb_build_array(id, company_id, movement_id, line_number, inventory_item_id, handling_unit_id, lot_code, expiry_date, from_warehouse_id, from_location_id, from_stock_status, to_warehouse_id, to_location_id, to_stock_status, quantity_base)::text, E'\n' ORDER BY id), ''))) FROM inventory_movement_lines),
  'label_prints', (SELECT jsonb_build_object('rows', count(*), 'fingerprint', md5(coalesce(string_agg(jsonb_build_array(id, company_id, inventory_item_id, inventory_lot_id, inventory_lot_detail_id, handling_unit_id, idempotency_key, quantity_printed, print_date, reason, label_snapshot, printed_by, printed_at)::text, E'\n' ORDER BY id), ''))) FROM inventory_label_prints),
  'valuation_settings', (SELECT jsonb_build_object('rows', count(*), 'fingerprint', md5(coalesce(string_agg(jsonb_build_array(company_id, currency, opened_at, opened_by, opening_reference, opening_fingerprint, physical_snapshot)::text, E'\n' ORDER BY company_id), ''))) FROM inventory_valuation_settings),
  'cost_averages', (SELECT jsonb_build_object('rows', count(*), 'quantity_base', coalesce(sum(quantity_base), 0), 'inventory_value', coalesce(sum(inventory_value), 0), 'fingerprint', md5(coalesce(string_agg(jsonb_build_array(company_id, inventory_item_id, quantity_base, inventory_value, average_unit_cost)::text, E'\n' ORDER BY company_id, inventory_item_id), ''))) FROM inventory_cost_averages),
  'valuation_entries', (SELECT jsonb_build_object('rows', count(*), 'quantity_base', coalesce(sum(quantity_base), 0), 'source_value', coalesce(sum(source_value), 0), 'fingerprint', md5(coalesce(string_agg(jsonb_build_array(id, company_id, inventory_item_id, sequence, kind, quantity_base, source_value, original_entry_id, movement_line_id, purchase_detail_id, retaceo_id, source_reference, idempotency_key, fingerprint, balance_quantity, balance_value)::text, E'\n' ORDER BY id), ''))) FROM inventory_valuation_entries),
  'retaceo_applications', (SELECT jsonb_build_object('rows', count(*), 'fingerprint', md5(coalesce(string_agg(jsonb_build_array(id, company_id, retaceo_id, purchase_id, applied_at, applied_by, summary)::text, E'\n' ORDER BY id), ''))) FROM inventory_retaceo_applications),
  'purchases', (SELECT jsonb_build_object('rows', count(*), 'id_fingerprint', md5(coalesce(string_agg(id::text, E'\n' ORDER BY id), ''))) FROM purchases)
));